function generate(rand, size) {
  const n = size === 'large' ? 100 : 1 + Math.floor(rand() * 10);
  const spread = size === 'large' ? 1 + Math.floor(rand() * 100) : 1 + Math.floor(rand() * 4);
  const base = 1 + Math.floor(rand() * (101 - spread));
  const nums = Array.from({ length: n }, () => base + Math.floor(rand() * spread));
  const k = size === 'large' ? 1 + Math.floor(rand() * 100) : 1 + Math.floor(rand() * 8);
  return [nums, k];
}
